document.addEventListener("DOMContentLoaded",function(){const n=document.querySelectorAll(".tpr-autocomplete-container");n.forEach((n,t)=>{let r=n.getAttribute("data-autocomplete-url");const i=n.querySelector(".govuk-input");i.style.display="none";let u=i.getAttribute("name");i.removeAttribute("name");let f=i.getAttribute("placeholder");accessibleAutocomplete({element:n,id:`tpr-autocomplete__input-${t+1}`,source:function(n,t){fetch(r).then(n=>n.json()).then(i=>{const r=i.filter(t=>t.title.toLowerCase().includes(n.toLowerCase())).map(n=>n.title);t(r.slice(0,5))}).catch(n=>{console.error("An error has occured with autocomplete fetch operation:",n)})},minLength:2,placeholder:f,inputClasses:"govuk-input",name:u})})});